import unittest
from datetime import date

from health_oracle import (
    METRICS,
    format_associations,
    format_trend,
    normalize_payload,
    parse_question,
    pearson_correlation,
)


class HealthOracleTests(unittest.TestCase):
    """Cover local question routing and evidence calculations with synthetic data."""

    def test_question_selects_only_named_metrics(self) -> None:
        self.assertEqual(parse_question("Compare my HRV and sleep"), ["hrv", "sleep"])
        self.assertEqual(parse_question("How did my sleep change?"), ["sleep"])
        self.assertEqual(
            parse_question("How does heart rate variability relate to sleep?"),
            ["hrv", "sleep"],
        )
        self.assertEqual(parse_question("Tell me a joke"), [])

    def test_normalize_payload_extracts_dated_nested_values(self) -> None:
        payload = {
            "data": [
                {
                    "calendarDate": "2026-10-20",
                    "hrvSummary": {"lastNightAvg": 52, "weeklyAvg": 48},
                },
                {
                    "calendarDate": "2026-10-21",
                    "hrvSummary": {"lastNightAvg": 55, "weeklyAvg": 49},
                },
            ]
        }

        result = normalize_payload(payload, METRICS["hrv"])

        self.assertEqual(result["lastNightAvg"][date(2026, 10, 20)], 52.0)
        self.assertEqual(result["weeklyAvg"][date(2026, 10, 21)], 49.0)

    def test_sleep_duration_is_reported_in_hours(self) -> None:
        payload = {
            "data": [
                {"calendarDate": "2026-10-20", "sleepTimeSeconds": 25200},
                {"calendarDate": "2026-10-21", "sleepTimeSeconds": 28800},
            ]
        }
        readings = normalize_payload(payload, METRICS["sleep"])

        report = format_trend("sleep", readings, date(2026, 10, 20), date(2026, 10, 21))

        self.assertIn("Latest: 8.0 hours on 2026-10-21", report)
        self.assertIn("Evidence: 2 dated readings", report)

    def test_associations_require_fourteen_shared_dates_and_are_descriptive(self) -> None:
        days = [date(2026, 10, day) for day in range(1, 15)]
        datasets = {
            "hrv": {"lastNightAvg": {day: float(index) for index, day in enumerate(days)}},
            "steps": {"totalSteps": {day: float(index * 1000) for index, day in enumerate(days)}},
        }

        report = format_associations(["hrv", "steps"], datasets, days[0], days[-1])

        self.assertIn("r=+1.00 across 14 same-day readings", report)
        self.assertIn("do not show that one measurement causes another", report)

    def test_associations_decline_sparse_samples(self) -> None:
        days = [date(2026, 10, day) for day in range(1, 8)]
        datasets = {
            "hrv": {"lastNightAvg": {day: float(index) for index, day in enumerate(days)}},
            "steps": {"totalSteps": {day: float(index * 1000) for index, day in enumerate(days)}},
        }

        report = format_associations(["hrv", "steps"], datasets, days[0], days[-1])

        self.assertIn("need 14", report)

    def test_correlation_returns_none_for_constant_series(self) -> None:
        self.assertIsNone(pearson_correlation([1, 1, 1], [2, 3, 4]))


if __name__ == "__main__":
    unittest.main()